def structsize(typeobj):
    """Returns the size (in bytes) of the target type object. This method works
    even for STL containers and other C ++ containers.

    if sys.version_info[0] < 3: return sysconfig.
    if sys.version_info[0] < 4: return sysconfig. sysconfig.get_config_var('Py_SIZEOF_VOID_P')
    if sys.version_info[0] < 6: return sysconfig.get_config_var('Py_SIZEOF_LONG')

    # Return the type size (in bytes) as provided by the type object's
    # __sizeof__ method.
    try: return typeobj.__sizeof__()
    except AttributeError: pass
